/* Separate browser-local fresh-start workspace, leaving the sample demo intact. */
const cleanAgencyMode=true;
const demoStorageKey='sevlink-zero-launch-v1';
function initialDemoState(){return cleanAgencyMode?{agencies:[],members:[],properties:[],tenants:[],jobs:[],plans:[],messages:[],branding:{},subbies:[],privateBookings:[],featureExamples:4,privatePlannerVersion:1,authorityDemoVersion:1,cleanStart:true}:structuredClone(seed)}
function createFreshAgency(){openForm('Create your agency workspace.',field('Agency name','name','')+field('Your name · agency administrator','contact','')+field('Email','email','','email')+field('Phone','phone','','tel')+field('Service area','area','')+'<div class="notice">This test workspace saves in this browser. No password, real account or invitation email is created.</div>','Create agency workspace',async d=>{const values=Object.fromEntries(d);if(!String(values.name||'').trim()||!String(values.contact||'').trim())return;if(await commit(()=>{const a={id:id('a'),...values,accountType:'agency'};state.agencies.push(a);agency=a.id;activeMember='admin';tenant='';role='manager';view='overview'})){modal.close();render();toast('Agency created. Add your property managers next.')}})}
const renderBeforeAgencyStart=render;render=function(){if(cleanAgencyMode&&!state.agencies.length){document.body.classList.add('agency-welcome');$('#nav').innerHTML='';app.innerHTML=`<div class="panel" style="max-width:680px;margin:36px auto;padding:32px"><span class="eyebrow">WELCOME TO SEVLINK</span><h1>Your agency starts here.</h1><p>Create your agency, add your property managers, load properties and link tenants. Then report and manage your first repair.</p><div class="notice">A clean test workspace: no sample agencies, properties, tenants, repairs or invoices. Records save only in this browser.</div><button class="primary" onclick="createFreshAgency()">Create agency workspace →</button><p><small>Test registration only. Live sign-in and email invitations are not connected.</small></p></div>`;return}document.body.classList.remove('agency-welcome');renderBeforeAgencyStart();if(!cleanAgencyMode)return;const samples=app.querySelector('[onclick="resetDemo()"]');if(samples)samples.parentElement.remove();if(role==='manager'&&isAgencyAdmin()&&view==='overview'){const pm=state.members.filter(m=>m.agency===agency).length,props=state.properties.filter(p=>p.agency===agency).length,tenants=state.tenants.filter(t=>t.agency===agency).length,jobs=state.jobs.filter(j=>j.agency===agency).length;app.insertAdjacentHTML('afterbegin',`<section class="panel" style="margin-bottom:20px"><span class="eyebrow">GET YOUR AGENCY READY</span><h2>${esc(agencyNow().name)} · setup checklist</h2><p>Start with your team, then properties and tenants. Use the profile preview in the menu to test a PM’s own portfolio.</p><div class="cards"><button class="secondary" onclick="navigate('team')">${pm?'✓':'1.'} Property managers · ${pm}<br>Add your PM profiles</button><button class="secondary" onclick="navigate('properties')">${props?'✓':'2.'} Properties · ${props}<br>Add and assign properties</button><button class="secondary" onclick="navigate('tenants')">${tenants?'✓':'3.'} Tenants · ${tenants}<br>Link tenants to their property</button><button class="secondary" onclick="navigate('requests')">${jobs?'✓':'4.'} Repairs · ${jobs}<br>View repair jobs</button></div><p class="muted">To test a tenant report, choose Tenant view after linking a tenant. Return to Agency manager view to review and send it to Sevlink.</p></section>`)}};

